<?php

/**
 * <div id="class.curlstringfile" class="reference"> <h1 class="title">CURLStringFile 类</h1>  <div class="partintro"><p class="verinfo">(PHP 8 &gt;= 8.1.0)</p>  <div class="section" id="curlstringfile.intro">   <h2 class="title">简介</h2>   <p class="para">    <span class="classname"><strong class="classname">CURLStringFile</strong></span> 能够直接把一个变量作为文件上传。    这与 <span class="classname"><a href="https://php.net/manual/zh/class.curlfile.php" class="classname">CURLFile</a></span> 用法比较相似，但是它使用的是文件的内容，而不是文件名。    这个类或者 <span class="classname"><a href="https://php.net/manual/zh/class.curlfile.php" class="classname">CURLFile</a></span> 都需要和 <strong><span><a href="https://php.net/manual/zh/curl.constants.php#constant.curlopt-postfields">CURLOPT_POSTFIELDS</a></span></strong> 参数一同使用以上传文件。   </p>  </div>  <div class="section" id="curlstringfile.synopsis">   <h2 class="title">类摘要</h2>   <div class="classsynopsis"><div class="classsynopsisinfo">         <span class="modifier">class</span> <strong class="classname"><strong class="classname">CURLStringFile</strong></strong>     {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 属性 </div>    <div class="fieldsynopsis">     <span class="modifier">public</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>      <var class="varname"><a href="https://php.net/manual/zh/class.curlstringfile.php#curlstringfile.props.data">\$<var class="varname">data</var></a></var>;</div>    <div class="fieldsynopsis"><span class="modifier">public</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>      <var class="varname"><a href="https://php.net/manual/zh/class.curlstringfile.php#curlstringfile.props.postname">\$<var class="varname">postname</var></a></var>;</div>    <div class="fieldsynopsis"><span class="modifier">public</span>     <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>      <var class="varname"><a href="https://php.net/manual/zh/class.curlstringfile.php#curlstringfile.props.mime">\$<var class="varname">mime</var></a></var>;</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="constructorsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/curlstringfile.construct.php" class="methodname" style="color:#CC7832">__construct</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$data</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$postname</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$mime</span><span class="initializer"> = "application/octet-stream"</span></span>)</div>   }</div>  </div>    <div class="section" id="curlstringfile.props">   <h2 class="title">属性</h2>   <dl>         <dt id="curlstringfile.props.data"><var class="varname">data</var></dt>     <dd>      <p class="para">待上传的内容</p>     </dd>             <dt id="curlstringfile.props.postname"><var class="varname">postname</var></dt>     <dd>      <p class="para">上传数据中的文件名称</p>     </dd>             <dt id="curlstringfile.props.mime"><var class="varname">mime</var></dt>     <dd>      <p class="para">文件的 MIME 类型（默认为 <span class="literal">application/octet-stream</span>）。</p>     </dd>       </dl>  </div>  <div class="section" id="curlstringfile.seealso">   <h2 class="title">参见</h2>   <p class="para">    </p><ul class="simplelist">     <li>      <span class="function">{@link curl_setopt()}</span>     </li>     <li><span class="classname"><a href="https://php.net/manual/zh/class.curlfile.php" class="classname">CURLFile</a></span></li>    </ul>     </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link CURLStringFile::__construct} — 创建 CURLStringFile 对象</li></ul></div>
 * 
 * @since 8.1
 */
class CURLStringFile
{
    public string $data;
    public string $mime;
    public string $postname;

/**
 * <div id="curlstringfile.construct" class="refentry"> <div class="refnamediv">  <h1 class="refname">CURLStringFile::__construct</h1>  <p class="verinfo">(PHP 8 &gt;= 8.1.0)</p><p class="refpurpose"><span class="refname">CURLStringFile::__construct</span> — <span class="dc-title">创建 CURLStringFile 对象</span></p> </div> <div class="refsect1 description" id="refsect1-curlstringfile.construct-description">  <h3 class="title">说明</h3>  <div class="constructorsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>CURLStringFile::__construct</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$data</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$postname</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$mime</span><span class="initializer"> = "application/octet-stream"</span></span>)</div>  <p class="para rdfs-comment">   创建 <span class="classname"><a href="https://php.net/manual/zh/class.curlstringfile.php" class="classname">CURLStringFile</a></span> 对象，使用 <strong><span><a href="https://php.net/manual/zh/curl.constants.php#constant.curlopt-postfields">CURLOPT_POSTFIELDS</a></span></strong> 选项上传文件。  </p> </div> <div class="refsect1 parameters" id="refsect1-curlstringfile.construct-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">data</span></dt>    <dd>     <p class="para">      待上传的内容。     </p>    </dd>          <dt><span class="parameter" style="color:#3A95FF">postname</span></dt>    <dd>     <p class="para">      上传数据中的文件名称。     </p>    </dd>          <dt><span class="parameter" style="color:#3A95FF">mime</span></dt>    <dd>     <p class="para">      文件的 MIME 类型（默认为 <span class="literal">application/octet-stream</span>）。     </p>    </dd>     </dl> </div> <div class="refsect1 examples" id="refsect1-curlstringfile.construct-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">CURLStringFile::__construct()</strong></span> 示例</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br></span><span style="color: #FF8000">// http://example.com/upload.php:<br>&lt;?php<br>var_dump(\$_FILES);<br>var_dump(file_get_contents(\$_FILES['test_string']['tmp_name']));<br>?&gt;<br><br><br>// 创建一个 cURL 句柄<br></span><span style="color: #9876AA">\$ch </span><span style="color: #007700">= </span><span style="color: #9876AA">curl_init</span><span style="color: #007700">(</span><span style="color: #DD0000">'http://example.com/upload.php'</span><span style="color: #007700">);<br><br></span><span style="color: #FF8000">// 创建一个 CURLStringFile 对象<br></span><span style="color: #9876AA">\$cstringfile </span><span style="color: #007700">= new </span><span style="color: #9876AA">CURLStringFile</span><span style="color: #007700">(</span><span style="color: #DD0000">'test upload contents'</span><span style="color: #007700">,</span><span style="color: #DD0000">'test.txt'</span><span style="color: #007700">,</span><span style="color: #DD0000">'text/plain'</span><span style="color: #007700">);<br><br></span><span style="color: #FF8000">// 指定 POST 内容<br></span><span style="color: #9876AA">\$data </span><span style="color: #007700">= array(</span><span style="color: #DD0000">'test_string' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">\$cstringfile</span><span style="color: #007700">);<br></span><span style="color: #9876AA">curl_setopt</span><span style="color: #007700">(</span><span style="color: #9876AA">\$ch</span><span style="color: #007700">, </span><span style="color: #9876AA">CURLOPT_POST</span><span style="color: #007700">, </span><span style="color: #9876AA">1</span><span style="color: #007700">);<br></span><span style="color: #9876AA">curl_setopt</span><span style="color: #007700">(</span><span style="color: #9876AA">\$ch</span><span style="color: #007700">, </span><span style="color: #9876AA">CURLOPT_POSTFIELDS</span><span style="color: #007700">, </span><span style="color: #9876AA">\$data</span><span style="color: #007700">);<br><br></span><span style="color: #FF8000">// 执行句柄<br></span><span style="color: #9876AA">curl_exec</span><span style="color: #007700">(</span><span style="color: #9876AA">\$ch</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">array(1)&nbsp;{<br>&nbsp;&nbsp;["test_string"]=&gt;<br>&nbsp;&nbsp;array(5)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["name"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(8)&nbsp;"test.txt"<br>&nbsp;&nbsp;&nbsp;&nbsp;["type"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(10)&nbsp;"text/plain"<br>&nbsp;&nbsp;&nbsp;&nbsp;["tmp_name"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(14)&nbsp;"/tmp/phpTtaoCz"<br>&nbsp;&nbsp;&nbsp;&nbsp;["error"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(0)<br>&nbsp;&nbsp;&nbsp;&nbsp;["size"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(20)<br>&nbsp;&nbsp;}<br>}<br>string(20)&nbsp;"test&nbsp;upload&nbsp;contents"</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-curlstringfile.construct-seealso">  <h3 class="title">参见</h3>  <p class="para">   </p><ul class="simplelist">    <li><span class="function">{@link curl_setopt()} - 设置 cURL 传输选项</span></li>   </ul>   </div></div>
 */
    public function __construct(string $data, string $postname, string $mime = 'application/octet-stream') {}
}
